        this.id = UUID.randomUUID().toString();
        this.name = name;
        this.members = new ArrayList<>();
        this.expenses = new ArrayList<>();
        this.balanceSheets = new HashMap<>();
        this.lock = new ReentrantLock();
    }

    public String getId(){
        return this.id;
    }

