package projects.splitwise.service;

import java.util.List;

import projects.splitwise.model.*;

public class BalanceSheetService {
    public void updateBalances(Group group, User lender, List<Split> splits){
        BalanceSheet lenderBalanceSheet = group.getUserBalanceSheet(lender);
        double amountPaidByLender = 0;
        for (Split split : splits) {
            amountPaidByLender += split.getAmount();
            User borrower = split.getUser();
            BalanceSheet borrowerBalanceSheet = group.getUserBalanceSheet(borrower);
            double borrowedAmount = split.getAmount();
            borrowerBalanceSheet.addExpense(borrowedAmount);
            if(!borrower.equals(lender)){
                borrowerBalanceSheet.addBalance(lender, -borrowedAmount);
                lenderBalanceSheet.addBalance(borrower, borrowedAmount);
            }
        }
        lenderBalanceSheet.addPaid(amountPaidByLender);

    }
}

package projects.splitwise.service;

import java.util.*;

import projects.splitwise.model.*;

public class DebtSimplificationService {
    public void simplify(Group group) {
        group.getLock().lock();
        try {
            List<User> members = group.getMembers();
            Map<User, BalanceSheet> balanceSheets = group.getBalanceSheets();

            Map<User,Double> netBalances = new HashMap<>();

            for (User lender : members) {
                double totalPendingAmount = 0;
                Map<User, Double> balances = balanceSheets.get(lender).getBalances();
                for(double amount : balances.values()){
                    totalPendingAmount += amount;
                }
                netBalances.put(lender, totalPendingAmount);
                balanceSheets.get(lender).clear();
            }


            PriorityQueue<User> lenders = new PriorityQueue<>((a,b) -> Double.compare(netBalances.get(a), netBalances.get(b)));
            PriorityQueue<User> borrowers = new PriorityQueue<>((a,b) -> Double.compare(netBalances.get(b), netBalances.get(a)));

            for(User user: netBalances.keySet()){
                if(netBalances.get(user) > 0){
                    lenders.offer(user);
                } else if(netBalances.get(user) < 0){
                    borrowers.offer(user);
                }
            }

            while(!lenders.isEmpty() && !borrowers.isEmpty()){
                User lender = lenders.poll();
                User borrower = borrowers.poll();

                double lendedAmount = netBalances.get(lender);
                double borrowedAmount = netBalances.get(borrower);

                double settledAmount = Math.min(lendedAmount, -borrowedAmount);

                balanceSheets.get(lender).addBalance(borrower, settledAmount);
                balanceSheets.get(borrower).addBalance(lender, -settledAmount);

                netBalances.put(lender, lendedAmount-settledAmount);
                netBalances.put(borrower, borrowedAmount+settledAmount);

                if(netBalances.get(lender) > 0){
                    lenders.offer(lender);
                }
                if(netBalances.get(borrower) < 0){
                    borrowers.offer(borrower);
                }

            }
        } finally {
            group.getLock().unlock();
        }
    }
}

package projects.splitwise.service;

import java.util.List;
import java.util.Map;
import projects.splitwise.enums.*;
import projects.splitwise.factory.SplitStrategyFactory;
import projects.splitwise.model.*;
import projects.splitwise.repository.IExpenseRepository;
import projects.splitwise.strategy.ISplitStrategy;

public class ExpenseService {
    private final IExpenseRepository repository;
    private final BalanceSheetService balanceSheetService;

    public ExpenseService(IExpenseRepository repository, BalanceSheetService balanceSheetService) {
        this.repository = repository;
        this.balanceSheetService = balanceSheetService;
    }

    public String addExpense(Group group, String name, double amount, User lender, List<User> borrowers, SplitType splitType, Map<User, Double> meta){
        group.getLock().lock();
        try {
            ISplitStrategy strategy = SplitStrategyFactory.getSplitStrategy(splitType);
            List<Split> splits = strategy.split(amount, borrowers, meta);
            Expense expense = new Expense(name, amount, lender, borrowers, splitType, splits);
            repository.save(expense);
            group.addExpenses(expense);
            balanceSheetService.updateBalances(group, lender, splits);
            return expense.getId();
        } finally {
            group.getLock().unlock();
        }
    }
}

package projects.splitwise.service;

import java.util.*;
import projects.splitwise.enums.SplitType;
import projects.splitwise.model.*;
import projects.splitwise.repository.IGroupRepository;

public class GroupService {
    private final IGroupRepository repository;
    private final ExpenseService expenseService;
    private final DebtSimplificationService simplifier;
    private final PaymentService paymentService;

    public GroupService(IGroupRepository repository, ExpenseService expenseService, DebtSimplificationService simplifier, PaymentService paymentService) {
        this.repository = repository;
        this.expenseService = expenseService;
        this.simplifier = simplifier;
        this.paymentService = paymentService;
    }

    public String createGroup(String name, List<User> members){
        Group group = new Group(name);
        for (User member : members) {
            group.addMember(member);
        }
        repository.save(group);
        return group.getId();
    }

    public void addMember(String id, User user) throws IllegalArgumentException{
        Group group = repository.findById(id);
        if(group == null){
            throw new IllegalArgumentException("Did not find any grop with the id - " + id);
        }
        group.addMember(user);
    }

    private Group getGroupById(String id){
        return repository.findById(id);
    }

    public void addExpense(String groupId, String name, double amount, User lender, List<User> borrowers, SplitType splitType, Map<User, Double> meta){
        expenseService.addExpense(getGroupById(groupId), name, amount, lender,borrowers, splitType, meta);
    }

    public void simplifyDebts(String groupId){
        this.simplifier.simplify(getGroupById(groupId));
    }

    public String recordPayment(String groupId, User payer, User payee, double amount){
        return this.paymentService.recordPayment(getGroupById(groupId), payer, payee, amount);
    }

    public void displayBalances(String groupId){
        Group group = getGroupById(groupId);
        boolean anyDebt = false;
        for (User user : group.getMembers()) {
            BalanceSheet balanceSheet = group.getUserBalanceSheet(user);
            for (Map.Entry<User, Double> entry : balanceSheet.getBalances().entrySet()) {
                if (entry.getValue() > 0) {
                    anyDebt = true;
                    System.out.printf("%s owes %s: %.2f%n", entry.getKey().getName(), user.getName(), entry.getValue());
                }
            }
        }
        if (!anyDebt) {
            System.out.println("All settled up -- no outstanding balances.");
        }
    }
}

package projects.splitwise.service;

import projects.splitwise.model.*;
import projects.splitwise.repository.IPaymentRepository;

public class PaymentService {
    private final IPaymentRepository repository;

    public PaymentService(IPaymentRepository repository) {
        this.repository = repository;
    }

    public String recordPayment(Group group, User payer, User payee, double amount) {
        if (amount <= 0) {
            throw new IllegalArgumentException("Payment amount must be positive");
        }
        if (payer.equals(payee)) {
            throw new IllegalArgumentException("Payer and payee cannot be the same person");
        }

        group.getLock().lock();
        try {
            BalanceSheet payerSheet = group.getUserBalanceSheet(payer);
            BalanceSheet payeeSheet = group.getUserBalanceSheet(payee);

            payerSheet.addBalance(payee, amount);
            payeeSheet.addBalance(payer, -amount);

            Payment payment = new Payment(payer, payee, amount);
            repository.save(payment);
            return payment.getId();
        } finally {
            group.getLock().unlock();
        }
    }
}

package projects.splitwise.strategy;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import projects.splitwise.model.*;

public class EqualSplit implements ISplitStrategy {
    @Override
    public List<Split> split(double amount, List<User> participants, Map<User, Double> metadata) {
        List<Split> splits = new ArrayList<>();
        double amountPerUser = amount / participants.size();
        for (User participant : participants) {
            splits.add(new Split(participant, amountPerUser));
        }
        return splits;
    }
}

